// ServerInterface represents all server handlers.
type ServerInterface interface {
	// CreateAgent Create an agent with a default definition
	// (POST /agents)
	CreateAgent(w http.ResponseWriter, r *http.Request)
	// GetAgent An agent with its current definition, history and project overrides
	// (GET /agents/{handle})
	GetAgent(w http.ResponseWriter, r *http.Request, handle AgentHandle)
	// SaveAgentDefinition Save a new immutable definition version (runs in progress keep their snapshot)
	// (PUT /agents/{handle}/definition)
	SaveAgentDefinition(w http.ResponseWriter, r *http.Request, handle AgentHandle)
	// SetAgentOverride Set a project's override. An empty override removes it. Scopes can only tighten.
	// (PUT /agents/{handle}/overrides/{project})
	SetAgentOverride(w http.ResponseWriter, r *http.Request, handle AgentHandle, project string)
	// GetResolvedDefinition The definition merged with a project's override, as a run would snapshot it
	// (GET /agents/{handle}/resolved)
	GetResolvedDefinition(w http.ResponseWriter, r *http.Request, handle AgentHandle, params GetResolvedDefinitionParams)
	// ListAgentTokens Tokens for unmanaged sessions (bring your own agent)
	// (GET /agents/{handle}/tokens)
	ListAgentTokens(w http.ResponseWriter, r *http.Request, handle AgentHandle)
	// CreateAgentToken Mint a token. The plaintext is returned once and never stored.
	// (POST /agents/{handle}/tokens)
	CreateAgentToken(w http.ResponseWriter, r *http.Request, handle AgentHandle)
	// RevokeAgentToken Revoke a token immediately
	// (DELETE /agents/{handle}/tokens/{tokenId})
	RevokeAgentToken(w http.ResponseWriter, r *http.Request, handle AgentHandle, tokenId openapi_types.UUID)
	// DecideApproval Approve or deny an agent's request. The run resumes with the decision.
	// (POST /approvals/{id}/{decision})
	DecideApproval(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, decision string)
	// ListArtifacts Artifacts, newest first, with per-type counts for the tabs
	// (GET /artifacts)
	ListArtifacts(w http.ResponseWriter, r *http.Request, params ListArtifactsParams)
	// CreateArtifact Create an artifact from markdown (body_md) or an uploaded file
	// (POST /artifacts)
	CreateArtifact(w http.ResponseWriter, r *http.Request)
	// GetArtifact An artifact with its current version, outline, readers, history and tickets
	// (GET /artifacts/{id})
	GetArtifact(w http.ResponseWriter, r *http.Request, id ArtifactId)
	// UpdateArtifact Edit title, summary or epic (contents change via new versions)
	// (PATCH /artifacts/{id})
	UpdateArtifact(w http.ResponseWriter, r *http.Request, id ArtifactId)
	// CreateArtifactVersion Add a version (markdown or file); it becomes current
	// (POST /artifacts/{id}/versions)
	CreateArtifactVersion(w http.ResponseWriter, r *http.Request, id ArtifactId)
	// GetArtifactContent The raw content of one version (markdown text or the stored file)
	// (GET /artifacts/{id}/versions/{versionId}/content)
	GetArtifactContent(w http.ResponseWriter, r *http.Request, id ArtifactId, versionId openapi_types.UUID, params GetArtifactContentParams)
	// GetBootstrap Everything the shell and pickers need in one call (`me` is the local user)
	// (GET /bootstrap)
	GetBootstrap(w http.ResponseWriter, r *http.Request)
	// DeleteCriterion Remove an acceptance criterion
	// (DELETE /criteria/{id})
	DeleteCriterion(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// UpdateCriterion Edit or tick an acceptance criterion
	// (PATCH /criteria/{id})
	UpdateCriterion(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// GetHealth Liveness and dependency status
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetBacklinks Linked and unlinked mentions of an artifact, ticket, epic or agent
	// (GET /knowledge/backlinks)
	GetBacklinks(w http.ResponseWriter, r *http.Request, params GetBacklinksParams)
	// GetGraph The local link graph around a node (1–2 hops, both directions)
	// (GET /knowledge/graph)
	GetGraph(w http.ResponseWriter, r *http.Request, params GetGraphParams)
	// LinkMention Turn the first unlinked mention of a target in a source into a [[link]]
	// (POST /knowledge/link-mention)
	LinkMention(w http.ResponseWriter, r *http.Request)
	// ResolveLinks Resolve [[link]] texts to what they point at (for rendering)
	// (GET /knowledge/resolve)
	ResolveLinks(w http.ResponseWriter, r *http.Request, params ResolveLinksParams)
	// SearchKnowledge Full-text search over pages, artifacts and tickets, boosted by links
	// (GET /knowledge/search)
	SearchKnowledge(w http.ResponseWriter, r *http.Request, params SearchKnowledgeParams)
	// SuggestLinks [[ autocomplete over pages, artifacts, tickets, epics and agents
	// (GET /knowledge/suggest)
	SuggestLinks(w http.ResponseWriter, r *http.Request, params SuggestLinksParams)
	// GetRun A run with its turns, plan, approvals and events (the run log)
	// (GET /runs/{id})
	GetRun(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params GetRunParams)
	// ControlRun Pause, resume or cancel a run
	// (POST /runs/{id}/{action})
	ControlRun(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, action string)
	// ListSecrets Secret names and metadata (values are never returned)
	// (GET /secrets)
	ListSecrets(w http.ResponseWriter, r *http.Request)
	// SetSecret Create or replace a secret's value (409 when SECRETS_KEY isn't set)
	// (PUT /secrets)
	SetSecret(w http.ResponseWriter, r *http.Request)
	// DeleteSecret Delete a secret
	// (DELETE /secrets/{id})
	DeleteSecret(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// ListTickets List tickets for a view, with optional filters
	// (GET /tickets)
	ListTickets(w http.ResponseWriter, r *http.Request, params ListTicketsParams)
	// CreateTicket Create a ticket
	// (POST /tickets)
	CreateTicket(w http.ResponseWriter, r *http.Request)
	// BulkUpdateTickets Apply one patch to many tickets
	// (POST /tickets/bulk)
	BulkUpdateTickets(w http.ResponseWriter, r *http.Request)
	// GetTicket A ticket with its criteria
	// (GET /tickets/{key})
	GetTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// UpdateTicket Change ticket fields. Omitted fields are untouched; null clears.
	// (PATCH /tickets/{key})
	UpdateTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ListTicketActivity The ticket timeline, oldest first
	// (GET /tickets/{key}/activity)
	ListTicketActivity(w http.ResponseWriter, r *http.Request, key TicketKey)
	// AttachArtifact Attach an artifact to a ticket as context (or as generated output)
	// (POST /tickets/{key}/artifacts)
	AttachArtifact(w http.ResponseWriter, r *http.Request, key TicketKey)
	// DetachArtifact Remove an artifact from a ticket
	// (DELETE /tickets/{key}/artifacts/{artifactId})
	DetachArtifact(w http.ResponseWriter, r *http.Request, key TicketKey, artifactId openapi_types.UUID)
	// CreateComment Comment on a ticket (appears in the timeline)
	// (POST /tickets/{key}/comments)
	CreateComment(w http.ResponseWriter, r *http.Request, key TicketKey)
	// CreateCriterion Add an acceptance criterion
	// (POST /tickets/{key}/criteria)
	CreateCriterion(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ExportWiki Every page as an Obsidian-compatible vault (zip of markdown files)
	// (GET /wiki/export)
	ExportWiki(w http.ResponseWriter, r *http.Request)
	// ImportWiki Import a vault zip; each .md file creates or replaces the page at its path
	// (POST /wiki/import)
	ImportWiki(w http.ResponseWriter, r *http.Request)
	// GetWikiPage A page by path (or a renamed page's old path)
	// (GET /wiki/page)
	GetWikiPage(w http.ResponseWriter, r *http.Request, params GetWikiPageParams)
	// ListWikiPages Every wiki page (the page tree), with pending suggestion counts
	// (GET /wiki/pages)
	ListWikiPages(w http.ResponseWriter, r *http.Request)
	// CreateWikiPage Create a page at a path
	// (POST /wiki/pages)
	CreateWikiPage(w http.ResponseWriter, r *http.Request)
	// SaveWikiPage Save a page's body (a new version, silently) and/or move it to a new path
	// (PUT /wiki/pages/{id})
	SaveWikiPage(w http.ResponseWriter, r *http.Request, id ArtifactId)
	// ListWikiSuggestions Agent edits waiting for a person, oldest first
	// (GET /wiki/suggestions)
	ListWikiSuggestions(w http.ResponseWriter, r *http.Request, params ListWikiSuggestionsParams)
	// DecideWikiSuggestion Accept (publish as the next version) or reject a suggestion
	// (POST /wiki/suggestions/{versionId}/{decision})
	DecideWikiSuggestion(w http.ResponseWriter, r *http.Request, versionId openapi_types.UUID, decision string)
}

